// ---------------------------------------------------------------------------
// 3. Brand hero — /brand/<slug>
// ---------------------------------------------------------------------------

/**
 * Use a slug that is NOT in BRAND_COVER_IMAGES (hallab-1881, apple,
 * sables-gourmets, salma). When a static cover PNG exists, it takes priority
 * over brand?.image and is a local file — not a catalog proxy URL — so
 * buildCatalogHeroImageSrcset returns null and no srcset is generated.
 * "test-brand" forces the code to fall back to brand?.image which we supply
 * as a catalog proxy URL.
 */
const BRAND_SLUG = "test-brand";

test.describe("Brand hero image srcset", () => {
  test.beforeEach(async ({ page }) => {
    await stubCurrencyAndGeo(page);

    // Brands endpoint — return our test brand with a catalog proxy image URL.
    await page.route("**/api/woo/brands**", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          ok: true,
          brands: [
            {
              id: BRAND_SLUG,
              name: "Test Brand",
              slug: BRAND_SLUG,
              image: `/api/catalog/brand-image/${BRAND_SLUG}`,
            },
          ],
        }),
      }),
    );

    // Brand products fallback endpoint.
    await page.route("**/api/woo/brand-products**", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({ ok: true, products: [], count: 0 }),
      }),
    );

    // OS direct-fetch path.
    await page.route("**/os.presentail.com/api/products**", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({ products: [], totalPages: 1 }),
      }),
    );

    // Brand allowlist.
    await page.route("**/api/catalog/brand-allowlist", (route) =>
      route.fulfill({ status: 404, body: "" }),
    );

    // Catalog metadata (used by Navbar / search).
    await page.route(/\/api\/catalog\/metadata/, (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({ categories: [], occasions: [], brands: [] }),
      }),
    );

    // Stub the catalog brand-image proxy so ShimmerImage stays in the DOM.
    await page.route("**/api/catalog/brand-image/**", (route) =>
      route.fulfill({
        status: 200,
        contentType: "image/png",
        body: Buffer.from(TINY_PNG_B64, "base64"),
      }),
    );

    await seedLocation(page);
    await page.goto(`/en-lb/beirut/brand/${BRAND_SLUG}`);
  });

  test("hero <img> has a non-empty srcset containing ?w=1200", async ({
    page,
  }) => {
    // Wait for the brand name heading to confirm the page has rendered.
    await expect(
      page.getByRole("heading", { name: "Test Brand", level: 1 }),
    ).toBeVisible({ timeout: 15_000 });

    const heroImg = page
      .locator('img[srcset*="brand-image"]')
      .first();

    await expect(heroImg).toBeAttached({ timeout: 10_000 });

    const srcset = await heroImg.getAttribute("srcset");
    expect(srcset).toBeTruthy();
    expect(srcset).toContain("?w=1200");
  });

  test("hero srcset does NOT contain a raw URL without ?w= param", async ({
    page,
  }) => {
    await expect(
      page.getByRole("heading", { name: "Test Brand", level: 1 }),
    ).toBeVisible({ timeout: 15_000 });

    const heroImg = page
      .locator('img[srcset*="brand-image"]')
      .first();

    await expect(heroImg).toBeAttached({ timeout: 10_000 });

    const srcset = await heroImg.getAttribute("srcset");
    expect(srcset).toBeTruthy();

    const entries = (srcset ?? "").split(",").map((e) => e.trim());
    for (const entry of entries) {
      expect(entry).toContain("?w=");
    }
  });

  test("hero srcset contains the 800w and 1600w entries too", async ({
    page,
  }) => {
    await expect(
      page.getByRole("heading", { name: "Test Brand", level: 1 }),
    ).toBeVisible({ timeout: 15_000 });

    const heroImg = page
      .locator('img[srcset*="brand-image"]')
      .first();

    await expect(heroImg).toBeAttached({ timeout: 10_000 });

    const srcset = await heroImg.getAttribute("srcset");
    expect(srcset).toContain("?w=800");
    expect(srcset).toContain("?w=1600");
  });
});
